import { useEffect, useRef, useState } from 'react';
import { PageHeader } from '@kerfjs/ui/page-header';
import { StateBanner } from '@kerfjs/ui/state-banner';
import { EmptyState } from '@kerfjs/ui/empty-state';
import { LoadingSpinner } from '@kerfjs/ui/loading-spinner';
import '@kerfjs/ui/layout.css';

type Item = { id: string; title: string };
type Snapshot = { items: Item[] | null; pending: boolean; error: string | null };
export function ListWorkspace({ load, create }: {
  load: (signal: AbortSignal) => Promise<Item[]>; create: () => void;
}) {
  const [state, setState] = useState<Snapshot>({ items: null, pending: true, error: null });
  const active = useRef<AbortController | null>(null);
  const request = useRef(0);
  async function refresh() {
    active.current?.abort();
    const controller = new AbortController();
    active.current = controller;
    const sequence = ++request.current;
    setState(previous => ({ ...previous, pending: true, error: null }));
    try {
      const items = await load(controller.signal);
      if (!controller.signal.aborted && sequence === request.current)
        setState({ items, pending: false, error: null });
    } catch {
      if (!controller.signal.aborted && sequence === request.current)
        setState(previous => ({ ...previous, pending: false, error: 'Items could not be loaded. Please try again.' }));
    }
  }
  useEffect(() => { void refresh(); return () => { active.current?.abort(); ++request.current; }; }, [load]);
  const initial = state.items === null;
  return <main className="kui-layout" aria-labelledby="list-title">
    <PageHeader id="list-title" title="Items" />
    <div className="kui-pane-body">
      <button type="button" onClick={() => void refresh()} disabled={state.pending}>Refresh items</button>
      <div role="status" aria-live="polite" aria-atomic="true">
        {state.pending && <><LoadingSpinner aria-hidden="true" />{initial ? 'Loading items…' : 'Refreshing items; previous results remain visible.'}</>}
        {!state.pending && !state.error && state.items !== null && `${state.items.length} items loaded.`}
      </div>
      {state.error && <div role="alert">
        <StateBanner title="Unable to load items" description={state.error} />
        {!initial && <p>Showing previously loaded items.</p>}
        <button type="button" onClick={() => void refresh()}>Try again</button>
      </div>}
      <section aria-label="Items" aria-busy={state.pending}>
        {state.items?.length === 0 && <><EmptyState title="No items yet" description="Create an item to get started." /><button type="button" onClick={create}>Create item</button></>}
        {!!state.items?.length && <ul>{state.items.map(item => <li key={item.id}>{item.title}</li>)}</ul>}
      </section>
    </div>
  </main>;
}
// Transport, stale data, errors and actions belong to this application adapter.
// Public component property names should be checked against installed declarations.
